html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value is not none else "" }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form .ref td { font-size: 10.5px; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 12px 0 6px; }
.lpl-form .rule { min-height: 34px; white-space: pre-wrap; }
.lpl-form .sign { border: none; padding: 6px 0 0; }
.lpl-form .narrow { width: 9%; text-align: center; }
.lpl-form .scores td { text-align: center; font-weight: bold; }
</style>
<div class="lpl-form">
<h3>Performance Appraisal Report</h3>
<table>
<tr><th style="width:18%">Appraisal Cycle</th><td>{{ v(doc.appraisal_cycle) }}</td>
<th style="width:14%">Plant</th><td>{{ v(doc.branch) }}</td></tr>
<tr><th>Review Date</th><td>{{ day(doc.review_date) }}</td>
<th>Shared On</th><td>{{ day(doc.shared_on) }}</td></tr>
<tr><th>Appraised</th><td>{{ v(doc.appraised) }}</td>
<th>Average Score</th><td>{{ num(doc.average_score) }}%</td></tr>
<tr><th>Below the pass mark</th><td>{{ v(doc.below_pass) }}</td>
<th>Completion</th><td>{{ num(doc.completion) }}%</td></tr>
</table>

<table>
<tr><th style="width:4%">#</th><th>Employee</th><th style="width:18%">Department</th>
<th class="narrow">Score</th><th style="width:12%">Rating</th><th style="width:16%">Decision</th>
<th style="width:20%">Remarks</th></tr>
{%- for row in doc.employees %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.employee_name or row.employee) }}</td><td>{{ v(row.department) }}</td>
<td class="narrow">{{ num(row.total_score) }}</td><td>{{ v(row.band) }}</td><td>{{ v(row.decision) }}</td>
<td>{{ v(row.remarks) }}</td></tr>
{%- endfor %}
</table>

<h4>Management's Remarks</h4>
<div class="rule">{{ v(doc.management_remarks) }}</div>
<p>Shared with: {{ v(doc.shared_with) }}</p>
<p>Decided by {{ who(doc.decided_by) }} &hellip;&hellip;&hellip;&hellip; Date {{ day(doc.decided_on) }}
&hellip;&hellip;&hellip;&hellip;</p>
</div>
